using System.Collections;
using System.IO;
using System.Reflection;
using System.Runtime.Loader;
using System.Text.Json;
internal static class Program {
 const BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static;
 static Assembly host=null!;static Type engineType=null!,backendType=null!,nodeType=null!,leaseType=null!;static string evidence="";static int checks;static readonly List<string> failures=[];
 static object? Call(object value,string name,params object?[] args){var m=value.GetType().GetMethods(F).Single(m=>m.Name==name&&m.GetParameters().Length==args.Length);try{return m.Invoke(value,args);}catch(TargetInvocationException e)when(e.InnerException is not null){throw e.InnerException;}}
 static object? Field(object o,string n)=>o.GetType().GetField(n,F)!.GetValue(o);
 static void Field(object o,string n,object? v)=>o.GetType().GetField(n,F)!.SetValue(o,v);
 static object? Prop(object o,string n)=>o.GetType().GetProperty(n,F)!.GetValue(o);
 static void Prop(object o,string n,object? v)=>o.GetType().GetProperty(n,F)!.SetValue(o,v);
 static void Require(bool v,string why){if(!v)throw new InvalidOperationException(why);}
 static void Check(string n,Action a){checks++;try{a();Console.WriteLine("PASS "+n);}catch(Exception e){failures.Add(n+": "+e.Message);Console.WriteLine("FAIL "+n+": "+e.Message);}}
 static int Count(object? o)=>o is IEnumerable items?items.Cast<object>().Count():0;
 static string Code(Exception e)=>(string?)Prop(e,"Code")??e.GetType().Name;
 static JsonElement Empty(){using var d=JsonDocument.Parse("{}");return d.RootElement.Clone();}
 sealed class Fixture:IDisposable {
  public readonly object Engine;public object State=>Field(Engine,"state")!;public object? Backend;public readonly string LogRoot;
  Timer? timer;ManualResetEventSlim? armed;
  public Fixture(bool mock=false){LogRoot=Path.Combine(evidence,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(LogRoot);var options=host.GetType("YeManFanHost.HostOptions",true)!.GetMethod("Parse",F)!.Invoke(null,[mock?new[]{"--mock-handshake"}:Array.Empty<string>()]);var log=Activator.CreateInstance(host.GetType("YeManFanHost.HostDiagnosticLog",true)!,F,null,[LogRoot,0],null)!;Engine=Activator.CreateInstance(engineType,F,null,[options,log],null)!;Require(Field(Engine,"realBackend") is null,"safe fixture unexpectedly has device backend");}
  public object SeedCurve(double duty=100){var curve=Array.CreateInstance(nodeType,4);var temps=new[]{0d,40d,70d,100d};for(int i=0;i<4;i++)curve.SetValue(Activator.CreateInstance(nodeType,F,null,[temps[i],duty],null),i);Field(Engine,"activeCurve",curve);Prop(State,"ActiveCurve",curve);Prop(State,"State","Ready");Prop(State,"PowerState","On");return curve;}
  public object SeedLease(bool expired=true){var l=Activator.CreateInstance(leaseType,F,null,["fixture-owned-lease",11L,Environment.TickCount64+(expired?-1:60000),"fixture"],null)!;Prop(State,"Lease",l);Prop(State,"LeaseGeneration",11L);return l;}
  public void Expiry(string path){if(path=="timer")Call(Engine,"ExpireLease","fixture-owned-lease",11L);else if(path=="heartbeat"){try{Call(Engine,"Heartbeat","fixture-owned-lease",0L);throw new Exception("expired heartbeat was accepted");}catch(Exception e)when(Code(e)=="LEASE_INVALID") {}}else{try{Call(Engine,"AcquireControl");}catch(Exception e)when(Code(e)=="FAN_UNSUPPORTED") {}}}
  public void AssertRetained(){Require(Count(Field(Engine,"suspendedCurve"))==4,"involuntary expiry erased pending user control intent");Require(Field(Engine,"activeCurve") is null,"expired curve remained actively controlling");Require(Prop(State,"Lease") is null,"expired lease revived");Require(!(bool)Prop(State,"HardwareWritesEnabled")!,"expiry enabled hardware");}
  public void InstallBackend(string family){var opts=host.GetType("YeManFanHost.HostOptions",true)!.GetMethod("Parse",F)!.Invoke(null,[new[]{"--real-backend"}]);Backend=Activator.CreateInstance(backendType,F,null,[opts],null)!;var route=backendType.GetMethod("ResolveRouteForSelfTest",F)!.Invoke(null,["HandheldCompanion.Devices."+family]);Require(route is not null,"fixture route missing");Field(Backend,"routeOverrideForSelfTest",route);Field(Engine,"realBackend",Backend);}
  public void EmptySleep(){Call(Engine,"MarkSystemSuspendPending");Prop(State,"PowerState","Suspended");Prop(State,"State","Suspended");}
  public void Resume(long epoch=-1,long stamp=-1)=>Call(Engine,"ResumeForSystemPower",2L,epoch,stamp);
  public bool Blocked=>(bool)Prop(Backend!,"TemperatureWritesBlockedForSelfTest")!;
  public bool Notify(){Field(Backend!,"activeCurveDuties",new[]{100d,100d,100d,100d});Prop(Backend!,"IsOpen",true);armed=new();timer=new(_=>armed.Set(),null,Timeout.Infinite,Timeout.Infinite);Field(Backend!,"powerProfileWatchdog",timer);return (bool)Call(Backend!,"NotifyMsiFirmwareModeChanged",5L)!;}
  public void AwaitNotify()=>Require(armed!.Wait(2000),"accepted MSI edge did not arm existing one-shot timer");
  public void Dispose(){timer?.DisposeAsync().AsTask().GetAwaiter().GetResult();armed?.Dispose();if(Backend is not null){Field(Backend,"powerProfileWatchdog",null);Field(Backend,"activeCurveDuties",null);Field(Backend,"activeFanProfile",null);Prop(Backend,"IsOpen",false);Field(Engine,"realBackend",null);((IDisposable)Backend).Dispose();}Field(Engine,"activeCurve",null);Field(Engine,"suspendedCurve",null);Prop(State,"Lease",null);Prop(State,"PowerState","On");Prop(State,"State","AwaitingControl");((IDisposable)Engine).Dispose();}
 }
 static int Main(string[] args){if(args.Length!=2)throw new ArgumentException("candidate DLL and isolated evidence root required");var path=Path.GetFullPath(args[0]);evidence=Path.GetFullPath(args[1]);Directory.CreateDirectory(evidence);Environment.SetEnvironmentVariable("YEMANCC_SELFTEST_LOG_ROOT",evidence);AssemblyLoadContext.Default.Resolving+=(_,n)=>{var p=Path.Combine(Path.GetDirectoryName(path)!,n.Name+".dll");return File.Exists(p)?AssemblyLoadContext.Default.LoadFromAssemblyPath(p):null;};host=AssemblyLoadContext.Default.LoadFromAssemblyPath(path);engineType=host.GetType("YeManFanHost.FanHostEngine",true)!;backendType=host.GetType("YeManFanHost.RealHcBackend",true)!;nodeType=host.GetType("YeManFanHost.FanNode",true)!;leaseType=host.GetType("YeManFanHost.FanLease",true)!;
 foreach(var pathName in new[]{"heartbeat","timer","acquire"}) {
  Check(pathName+" involuntary lease expiry retains intent but restores inactive ownership",()=>{using var f=new Fixture();f.SeedCurve();f.SeedLease();f.Expiry(pathName);f.AssertRetained();Require((string)Prop(f.State,"State")! == "AwaitingControl","ordinary expired lease policy changed");});
  Check(pathName+" retained intent survives the subsequent real suspend entry",()=>{using var f=new Fixture();f.SeedCurve();f.SeedLease();f.Expiry(pathName);Call(f.Engine,"MarkSystemSuspendPending");Call(f.Engine,"SuspendForSystemPower");Require(Count(Field(f.Engine,"suspendedCurve"))==4,"late sleep froze an empty curve after expiry");Require(!(bool)Prop(f.State,"HardwareWritesEnabled")!,"sleep granted a write");});
  Check(pathName+" explicit intent cancellation cannot be resurrected by expiry",()=>{using var f=new Fixture();f.SeedCurve();f.SeedLease();Call(f.Engine,"CancelControlIntent");f.Expiry(pathName);Require(Field(f.Engine,"suspendedCurve") is null,"expiry resurrected explicit OFF");});
 }
 Check("foreign expired heartbeat never retains or clears current owner",()=>{using var f=new Fixture();var c=f.SeedCurve();var l=f.SeedLease();try{Call(f.Engine,"Heartbeat","foreign",0L);}catch(Exception e)when(Code(e)=="LEASE_INVALID"){}Require(ReferenceEquals(c,Field(f.Engine,"activeCurve"))&&ReferenceEquals(l,Prop(f.State,"Lease")),"foreign token touched current owner");Require(Field(f.Engine,"suspendedCurve") is null,"foreign token retained intent");});
 Check("old lease timer never retains or clears new owner",()=>{using var f=new Fixture();var c=f.SeedCurve();var l=f.SeedLease();Call(f.Engine,"ExpireLease","old",10L);Require(ReferenceEquals(c,Field(f.Engine,"activeCurve"))&&ReferenceEquals(l,Prop(f.State,"Lease")),"old timer touched current owner");Require(Field(f.Engine,"suspendedCurve") is null,"old timer retained intent");});
 foreach(var action in new[]{"Disable","Restore","Release"})Check(action+" clears expiry-retained intent before next sleep",()=>{using var f=new Fixture();f.SeedCurve();f.SeedLease();f.Expiry("heartbeat");Call(f.Engine,action,Empty());Require(Field(f.Engine,"suspendedCurve") is null,"explicit cleanup retained intent");Call(f.Engine,"MarkSystemSuspendPending");Call(f.Engine,"SuspendForSystemPower");Require(Field(f.Engine,"suspendedCurve") is null,"sleep revived OFF");});
 foreach(var family in new[]{"MSI.ClawA1M","MSI.ClawA2VM","MSI.ClawBZ2EM","MSI.ClawCG3EM","ROGAlly","GPD.GPDWin5","AYANEO2","OneXPlayerX1Mini","LegionGoTablet2","LokiMax6800U"})Check(family+" empty actual Engine resume releases only its current backend write gate",()=>{using var f=new Fixture();f.InstallBackend(family);f.EmptySleep();Require(f.Blocked,"real sleep did not close gate");f.Resume();Require(!f.Blocked,"completed empty resume left backend background writes blocked");Require((string)Prop(f.State,"State")! == "AwaitingControl","empty resume pretended HC ready");Require(!(bool)Prop(f.State,"OpenCalled")!&&!(bool)Prop(f.State,"OpenEventsCalled")!&&!(bool)Prop(f.State,"HardwareWritesEnabled")!&&Prop(f.State,"Lease") is null,"empty resume opened/wrote/granted lease");});
 foreach(var family in new[]{"MSI.ClawA1M","MSI.ClawA2VM","MSI.ClawBZ2EM","MSI.ClawCG3EM"})Check(family+" first post-empty-resume MSI mode edge can arm existing replay owner",()=>{using var f=new Fixture();f.InstallBackend(family);f.EmptySleep();f.Resume();Require(f.Notify(),"successful later Open/Enable state still rejected every MSI notification");f.AwaitNotify();});
 Check("stale resume authorization cannot lift real sleep gate",()=>{using var f=new Fixture();f.InstallBackend("MSI.ClawCG3EM");f.EmptySleep();f.Resume(0,0);Require(f.Blocked,"stale resume lifted sleep gate");});
 Check("terminal close cannot be lifted by empty resume",()=>{using var f=new Fixture();f.InstallBackend("MSI.ClawCG3EM");f.EmptySleep();Call(f.Backend!,"BlockWritesForClose");f.Resume();Require(f.Blocked,"empty resume lifted terminal close");Require((string)Prop(f.State,"PowerOperationStatus")! != "completed","unreleased close falsely committed an empty resume");});
 Check("a new sleep after empty completion revokes background writes again",()=>{using var f=new Fixture();f.InstallBackend("MSI.ClawCG3EM");f.EmptySleep();f.Resume();Call(f.Backend!,"BlockWritesForSuspend");Require(f.Blocked,"new sleep failed to close gate");Require(!f.Notify(),"new sleep allowed MSI notification to arm");});
 Check("actual accepted Enable after cancellation retains the new explicit curve",()=>{using var f=new Fixture(mock:true);Call(f.Engine,"Open");Call(f.Engine,"OpenEvents");var lease=Call(f.Engine,"AcquireControl")!;Call(f.Engine,"CancelControlIntent");using var body=JsonDocument.Parse(JsonSerializer.Serialize(new{leaseId=(string)Prop(lease,"LeaseId")!,nodes=new[]{new{tempC=0,dutyPercent=65},new{tempC=40,dutyPercent=65},new{tempC=70,dutyPercent=65},new{tempC=100,dutyPercent=65}}}));Call(f.Engine,"Enable",body.RootElement);f.SeedLease();f.Expiry("heartbeat");Require(Count(Field(f.Engine,"suspendedCurve"))==4,"new explicit control did not regain retention");var first=((IEnumerable)Field(f.Engine,"suspendedCurve")!).Cast<object>().First();Require(Convert.ToDouble(Prop(first,"DutyPercent"))==65,"old intent replaced new curve");});
 Check("explicit intent-only OFF cannot be refrozen by later sleep",()=>{using var f=new Fixture();f.SeedCurve();Call(f.Engine,"CancelControlIntent");Call(f.Engine,"MarkSystemSuspendPending");Call(f.Engine,"SuspendForSystemPower");Require(Field(f.Engine,"suspendedCurve") is null,"sleep refroze explicitly cancelled control");});
 Check("fixture never loads HC or executes a hardware boundary",()=>Require(!AppDomain.CurrentDomain.GetAssemblies().Any(a=>a.GetName().Name=="HandheldCompanion"),"HC DLL unexpectedly loaded"));
 Console.WriteLine(JsonSerializer.Serialize(new{ok=failures.Count==0,checks,failures,hardwareCalls=0,hostDllSha256=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(path))).ToLowerInvariant(),scope="actual production expiry+Suspend/empty-Resume and backend write-gate/Notify; accepted curve and later Open/Enable state seeded; watchdog callback inert; no HC/device/native power"}));return failures.Count==0?0:1;
 }
